DEFAULT_MAX_CONFIG_SIZE = 1024 * 1024

JSON_EXTENSION = '.json'

DIR_MODE = 0o750   # 488
FILE_MODE = 0o640  # 416

JSON_INDENT = 2

SERVER_HOST = '0.0.0.0'
SERVER_PORT = 8080

INDEX_TEMPLATE_NAME = 'config_manager.html'
VIEW_TEMPLATE_NAME = 'view_config.html'

