def _is_within(base, path):
    """Return True if `path` resolves to `base` or a location inside it."""
    base = os.path.realpath(base)
    path = os.path.realpath(path)
    try:
        return os.path.commonpath([base, path]) == base
    except ValueError:
        return False


class ThemeManager:

