# Constants
# --------------------------------------------------------------------------

DEFAULT_THEMES_DIR = '/var/www/themes'
DEFAULT_STATIC_DIR = '/var/www/static'
DEFAULT_ALLOWED_ASSET_TYPES = {'.css', '.js', '.png', '.jpg', '.gif', '.json'}

DIR_MODE = 0o750   # 488
FILE_MODE = 0o640  # 416

SERVER_HOST = '0.0.0.0'
SERVER_PORT = 8080

THEME_MANIFEST_NAME = 'theme.json'
SAMPLE_THEMES = ['dark', 'light', 'corporate']
