        file_path = _log_path(filename)
        try:
            with open(file_path, 'a') as f:
                timestamp = datetime.now().strftime(ENTRY_TIMESTAMP_FORMAT)
                f.write(f'[{timestamp}] {message}\n')
            return True
        except Exception:
            return False


