    """Return a copy of ``mapping`` with every value converted to an escaped string."""
    return {key: escape(str(value)) for (key, value) in mapping.items()}


def _list_allowed_files(directory, allowed_extensions):
    """List regular files in ``directory`` whose names pass the allowed-file check."""
    return [
        name for name in os.listdir(directory)
