        return {
            'title': self.title,
            'author': self.author,
            'tags': self.tags,
            'created': self.created.isoformat(),
            'modified': self.modified.isoformat(),
        }


class DocumentProcessor:

    def __init__(self):
        self.cache = {}
        self.metadata = DocumentMetadata()
        self.parsed_content = None
        self.analytics = _new_analytics()

