        self.annotations = []
        self.processed_content = None


def _build_json_plugin_class(config: Dict[str, Any]):
    """Create a plugin class that applies the simple transform given in ``config``."""

    class JsonPlugin:
        is_plugin = True

        def __init__(self):
            self.config = config

        def process(self, document):
            result = document.content
            settings = self.config['settings']
            if 'transform' in settings:
                transform = settings['transform']
                if transform == 'uppercase':
                    result = result.upper()
                elif transform == 'lowercase':
                    result = result.lower()
            return result

    return JsonPlugin


class PluginManager:

    def __init__(self):
        self.plugins = {}
        self.loaded_plugins = {}
        self.document_cache = {}
        self.plugin_data_dir = PLUGIN_DATA_DIR
        os.makedirs(self.plugin_data_dir, exist_ok=True)

    # ------------------------------------------------------------------
    # Loading
    # ------------------------------------------------------------------
    def load_plugin(self, plugin_path: str) -> bool:
        try:
            if not os.path.exists(plugin_path):
                raise ValueError('Plugin file does not exist')
            if plugin_path.endswith('.py'):
                return self._load_python_plugin(plugin_path)
            elif plugin_path.endswith('.json'):
                return self._load_json_plugin(plugin_path)
            else:
                print(f'Unsupported plugin format: {plugin_path}')
                return False
        except Exception as e:
            print(f'Failed to load plugin {plugin_path}: {str(e)}')
            return False

    def _register_plugin(self, name: str, plugin_class, plugin_type: str, path: str) -> None:
        self.plugins[name] = plugin_class
