        with open(data_file, 'w', encoding='utf-8') as f:
            json.dump(allowed_config, f, indent=2)

        plugin_class = _build_json_plugin_class(allowed_config)
        self._register_plugin(plugin_name, plugin_class, 'json', plugin_path)
        return True

