import hashlib
import datetime
import io
import pickle
from typing import Dict, List, Optional


class _RestrictedUnpickler(pickle.Unpickler):
    """Unpickler that only permits the types produced by export_records.

    Plain containers and primitives need no globals; the only global allowed
    is datetime.datetime (used for the 'last_updated' field). Anything else
    is rejected, so untrusted data cannot execute arbitrary code.
    """

    _ALLOWED_GLOBALS = {('datetime', 'datetime')}

    def find_class(self, module, name):
        if (module, name) in self._ALLOWED_GLOBALS:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(f'Forbidden global: {module}.{name}')


def _safe_loads(data: bytes):
    return _RestrictedUnpickler(io.BytesIO(data)).load()


class PatientRecord:

    def __init__(self, patient_id: str, name: str, dob: str):
        self.patient_id = patient_id
        self.name = name
        self.dob = dob
        self.medical_history: List[Dict] = []
        self.allergies: List[str] = []
