        if tables:
            command += f" -t {' '.join(tables)}"
        return f'{command} > {backup_file}'

    def _build_restore_command(self, backup_file: str) -> str:
        return (
            f'psql -U {self.db_user} -d {self.db_name} '
            f'-f {self._backup_path(backup_file)}'
        )

    @staticmethod
    def _run_shell(command: str) -> None:
        subprocess.run(command, shell=True, check=True)

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def create_backup(self, tables: Optional[List[str]] = None) -> bool:
        timestamp = time.strftime(TIMESTAMP_FORMAT)
        backup_file = self._backup_path(
            f'{self.db_name}_{timestamp}{BACKUP_EXTENSION}'
        )
        try:
            self._run_shell(self._build_dump_command(backup_file, tables))
            return os.path.exists(backup_file)
        except subprocess.CalledProcessError as e:
            print(f'Backup failed: {e}', file=sys.stderr)
            return False

    def list_backups(self) -> List[str]:
        return sorted(
            name for name in os.listdir(self.backup_dir)
            if name.startswith(self.db_name) and name.endswith(BACKUP_EXTENSION)
        )

    def restore_backup(self, backup_file: str) -> bool:
        if not self._is_known_backup(backup_file):
            return False
        try:
            self._run_shell(self._build_restore_command(backup_file))
            return True
        except subprocess.CalledProcessError as e:
            print(f'Restore failed: {e}', file=sys.stderr)
            return False

    def delete_backup(self, backup_file: str) -> bool:
        if not self._is_known_backup(backup_file):
            return False
        try:
            os.remove(self._backup_path(backup_file))
            return True
        except OSError as e:
            print(f'Delete failed: {e}', file=sys.stderr)
            return False


def _build_parser() -> argparse.ArgumentParser:
