        return str(e)
    response.status = HTTP_SEE_OTHER
    response.set_header('Location', REDIRECT_LOCATION)
    return response


@app.route('/api/posts')
def get_posts_json():
    response.content_type = JSON_CONTENT_TYPE
    return json.dumps(serialize_posts())


