    with closing(get_db_connection()) as conn:
        c = conn.cursor()
        c.execute(INSERT_USER_SQL, (username, password_hash))
        conn.commit()


def _fetch_password_hash(username):
    with closing(get_db_connection()) as conn:
        c = conn.cursor()
        c.execute(SELECT_USER_PASSWORD_SQL, (username,))
        return c.fetchone()


