        self._write_json(admins)

    @staticmethod
    def _fetch_admins():
        db = Database()
        cursor = db.conn.cursor()
        cursor.execute(SELECT_ADMINS_SQL)
        return cursor.fetchall()


# ---------------------------------------------------------------------------
# Application wiring
# ---------------------------------------------------------------------------

ROUTES = [
    ('/register', RegisterHandler),
    ('/login', LoginHandler),
    ('/user/([0-9]+)', UserProfileHandler),
