STATUS_BAD_REQUEST = 400

BOOK_COLUMNS = (
    'book_id',
    'title',
    'author',
    'isbn',
    'published_date',
    'genre',
    'available_copies',
)

# ---------------------------------------------------------------------------
# SQL statements
