        if handler is None:
            return f'Unknown command: {cmd}'

        try:
            if not args:
                return handler()
            if ',' in args:
                return handler(*[arg.strip() for arg in args.split(',')])
            return handler(args)
        except Exception as e:
            return f'Error executing {cmd}: {str(e)}'


