EVAL_ITEM_NAME = 'item'

ROUTE_FILTER = '/api/products/filter'
ROUTE_DYNAMIC_FILTER = '/api/products/dynamic_filter'
ROUTE_SAFE_FILTER = '/api/products/safe_filter'
POST_METHODS = ['POST']


