SEARCH_RESULTS_TEMPLATE = '\n        <h2>Search Results</h2>\n        <ul>\n            %for user in results:\n                <li>{{user[\'name\']}} ({{user[\'age\']}})</li>\n            %end\n        </ul>\n        <a href="/">New Search</a>\n    '


